WITH flattened AS (SELECT id, customer_id, created_at, pos + 1 AS line_no, line.product_id, line.qty FROM carts LATERAL VIEW POSEXPLODE(items) e AS pos, line), with_windows AS (SELECT id, created_at, line_no, product_id, qty, AVG(product_id) OVER (PARTITION BY customer_id ORDER BY product_id ASC, id ASC, line_no ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS product_id_avg_3_prior, AVG(line_no) OVER w_grp AS line_no_avg_2, MIN(line_no) OVER w_part AS customer_id_min_line_no, COUNT(qty) OVER w_part AS customer_id_count_qty FROM flattened WINDOW w_grp AS (ORDER BY product_id ASC, id ASC, line_no ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY customer_id)), valid AS (SELECT id, created_at, line_no, product_id, qty, product_id_avg_3_prior, line_no_avg_2, customer_id_min_line_no, customer_id_count_qty, line_no + product_id AS line_no_plus_product_id, CAST(product_id AS STRING) AS product_id_num FROM with_windows WHERE created_at > TIMESTAMP '2025-03-01 12:00:00'), enriched AS (SELECT *, SUM(qty) OVER (ORDER BY line_no ASC, id ASC, line_no ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_qty, SUM(line_no) OVER (ORDER BY CAST(created_at AS BIGINT) ASC RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS line_no_sum_2h, SUM(qty) OVER w_ordered AS running_qty FROM valid WINDOW w_ordered AS (ORDER BY product_id_avg_3_prior ASC, id ASC, line_no ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched_carts AS (SELECT *, ROW_NUMBER() OVER (ORDER BY line_no DESC, id ASC, line_no ASC) AS row_seq, DENSE_RANK() OVER (ORDER BY product_id_avg_3_prior DESC) AS product_id_avg_3_prior_dense_rank, SUM(cumulative_qty) OVER (PARTITION BY MONTH(created_at) ORDER BY customer_id_min_line_no ASC, id ASC, line_no ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cumulative_qty, AVG(product_id) OVER (ORDER BY created_at ASC, id ASC, line_no ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS product_id_avg_3 FROM enriched WHERE customer_id_count_qty < 15) SELECT id, created_at, line_no, product_id, qty, line_no_avg_2, customer_id_min_line_no, customer_id_count_qty, line_no_plus_product_id FROM enriched_carts ORDER BY line_no_avg_2 ASC
